import{_ as v,v as u,C as h,o as r,c as o,a8 as l,j as e,a as t,e as d,E as g,p as c}from"./chunks/framework.CzFdGYtP.js";const m={key:0},b={key:1},y=JSON.parse('{"title":"Titiler Integration","description":"","frontmatter":{"title":"Titiler Integration","layout":"page"},"headers":[],"relativePath":"software-services/titiler/index.md","filePath":"software-services/titiler/index.md"}'),f={name:"software-services/titiler/index.md"},k=Object.assign(f,{setup(x){const i=c(!1),n=c(!0);return u(async()=>{try{const s=await fetch("https://api.explorer.eopf.copernicus.eu/raster/_mgmt/ping");i.value=s.ok}catch{i.value=!1}finally{n.value=!1}}),(s,a)=>{const p=h("FeaturesGallery");return r(),o("div",null,[a[2]||(a[2]=l('<h2 id="titiler-integration" tabindex="-1" data-v-66ea2533>Titiler Integration <img src="https://user-images.githubusercontent.com/10407788/172718020-c2378b7e-a0d4-406e-924c-8ffe54e61596.png" alt="Titiler Logo" style="height:100px;vertical-align:middle;margin-left:0.5rem;float:right;" data-v-66ea2533> <a class="header-anchor link" href="#titiler-integration" aria-label="Permalink to &quot;Titiler Integration &lt;img src=&quot;https://user-images.githubusercontent.com/10407788/172718020-c2378b7e-a0d4-406e-924c-8ffe54e61596.png&quot; alt=&quot;Titiler Logo&quot; style=&quot;height:100px;vertical-align:middle;margin-left:0.5rem;float:right;&quot; /&gt;&quot;" data-v-66ea2533>​</a></h2><h3 id="overview" tabindex="-1" data-v-66ea2533>Overview <a class="header-anchor link" href="#overview" aria-label="Permalink to &quot;Overview&quot;" data-v-66ea2533>​</a></h3><p data-v-66ea2533>This guide demonstrates how to use Titiler-EOPF, a specialized tile server that provides on-the-fly visualization of EOPF&#39;s Zarr-formatted satellite data. Unlike client-side processing, Titiler handles complex calculations server-side and delivers optimized tiles for web mapping applications.</p>',3)),n.value?(r(),o("div",m,[...a[0]||(a[0]=[e("div",{class:"tip custom-block"},[e("p",{class:"custom-block-title"},[t("💡 "),e("strong",null,[t("Checking "),e("a",{href:"https://api.explorer.eopf.copernicus.eu/raster",class:"link",target:"_blank",rel:"noreferrer"},"API"),t(" Status")]),t(":Verifying Titiler service availability...")])],-1)])])):d("",!0),i.value?d("",!0):(r(),o("div",b,[...a[1]||(a[1]=[e("div",{class:"warning custom-block"},[e("p",{class:"custom-block-title"},[t("⚠️ "),e("strong",null,[e("a",{href:"https://api.explorer.eopf.copernicus.eu/raster",class:"link",target:"_blank",rel:"noreferrer"},"API"),t(" Unavailable")]),t(":: The Titiler service appears to be temporarily unavailable. Some examples may not work as expected.")])],-1)])])),a[3]||(a[3]=l('<br data-v-66ea2533><div class="info custom-block" data-v-66ea2533><p class="custom-block-title" data-v-66ea2533><strong data-v-66ea2533><i class="mdi mdi-target" data-v-66ea2533></i> What You&#39;ll Learn</strong></p><p data-v-66ea2533>This integration guide covers server-side tile generation using EOPF&#39;s Titiler service, enabling you to build responsive web applications without handling complex data processing in the browser. Each example demonstrates practical implementation patterns for real-world applications.</p><p data-v-66ea2533><strong data-v-66ea2533>Sample Data</strong> used here are available in <a href="https://api.explorer.eopf.copernicus.eu/browser/external/api.explorer.eopf.copernicus.eu/stac/collections/sentinel-2-l2a" class="link" target="_blank" rel="noreferrer" data-v-66ea2533>the Sentinel-2 L2A collection in STAC Browser</a></p></div><h3 id="quick-start" tabindex="-1" data-v-66ea2533>Quick Start <a class="header-anchor link" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;" data-v-66ea2533>​</a></h3><br data-v-66ea2533><div class="info custom-block" data-v-66ea2533><p class="custom-block-title" data-v-66ea2533><strong data-v-66ea2533><i class="mdi mdi-rocket-launch" data-v-66ea2533></i> Get Started in 5 Minutes</strong></p><p data-v-66ea2533>Ready to dive in? Start with the <a href="./rgb" class="link" data-v-66ea2533>RGB Visualization example</a> to see Titiler serving EOPF tiles in a web map, then explore NDVI calculations and spatial cropping techniques</p></div><br data-v-66ea2533><div class="warning custom-block" data-v-66ea2533><p class="custom-block-title" data-v-66ea2533>⚠️ <strong data-v-66ea2533>Early Implementation</strong></p><p data-v-66ea2533>This Titiler integration represents an early implementation of EOPF data services. Data availability, API stability, and library alignment will evolve over time as the platform matures.</p></div><h3 id="api-documentation" tabindex="-1" data-v-66ea2533>API Documentation <a class="header-anchor link" href="#api-documentation" aria-label="Permalink to &quot;API Documentation&quot;" data-v-66ea2533>​</a></h3><div class="grid" data-v-66ea2533><div class="s12 m6" data-v-66ea2533><div class="info custom-block" data-v-66ea2533><p class="custom-block-title" data-v-66ea2533>Interactive API Docs</p><p data-v-66ea2533><a href="https://api.explorer.eopf.copernicus.eu/raster/api.html" class="link" target="_blank" rel="noreferrer" data-v-66ea2533>Swagger UI Documentation</a></p><p data-v-66ea2533>Complete API reference with interactive examples and endpoint testing.</p></div></div><div class="s12 m6" data-v-66ea2533><div class="info custom-block" data-v-66ea2533><p class="custom-block-title" data-v-66ea2533>Base URL</p><p data-v-66ea2533><a href="https://api.explorer.eopf.copernicus.eu/raster/" class="link" target="_blank" rel="noreferrer" data-v-66ea2533>https://api.explorer.eopf.copernicus.eu/raster/</a></p><p data-v-66ea2533>All tile endpoints use this base URL for production integration.</p><br data-v-66ea2533></div></div></div><h3 id="key-concepts" tabindex="-1" data-v-66ea2533>Key Concepts <a class="header-anchor link" href="#key-concepts" aria-label="Permalink to &quot;Key Concepts&quot;" data-v-66ea2533>​</a></h3><p data-v-66ea2533><strong data-v-66ea2533>Server-Side Processing</strong></p><p data-v-66ea2533>Titiler-EOPF performs all data processing server-side, including:</p><ul data-v-66ea2533><li data-v-66ea2533><strong data-v-66ea2533>On-the-fly tile generation</strong> from Zarr datasets</li><li data-v-66ea2533><strong data-v-66ea2533>Mathematical expressions</strong> for band combinations and indices</li><li data-v-66ea2533><strong data-v-66ea2533>Color enhancement</strong> with gamma correction and contrast adjustment</li><li data-v-66ea2533><strong data-v-66ea2533>Spatial operations</strong> like cropping and reprojection</li></ul><p data-v-66ea2533><strong data-v-66ea2533>Asset and Band Selection</strong></p><p data-v-66ea2533>Titiler resolves each item through the STAC API and reads bands from its assets. Band selection uses the format:</p><div class="language- vp-adaptive-theme" data-v-66ea2533><button title="Copy Code" class="copy" data-v-66ea2533></button><span class="lang" data-v-66ea2533></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0" data-v-66ea2533><code data-v-66ea2533><span class="line" data-v-66ea2533><span data-v-66ea2533>assets=reflectance|bands=b04,b03,b02</span></span></code></pre></div><ul data-v-66ea2533><li data-v-66ea2533><code data-v-66ea2533>reflectance</code> - STAC asset of the item (for Sentinel-2 L2A, the asset that holds the spectral bands)</li><li data-v-66ea2533><code data-v-66ea2533>bands=b04,b03,b02</code> - Bands to read from that asset, by band name (<code data-v-66ea2533>b04</code>) or by the common name the asset assigns to the band (<code data-v-66ea2533>red</code>)</li></ul><p data-v-66ea2533>To compute a band operation instead, pass an <code data-v-66ea2533>expression</code> in place of <code data-v-66ea2533>bands</code>. It references the asset&#39;s bands by name, for example NDVI from NIR (<code data-v-66ea2533>b08</code>) and red (<code data-v-66ea2533>b04</code>):</p><div class="language- vp-adaptive-theme" data-v-66ea2533><button title="Copy Code" class="copy" data-v-66ea2533></button><span class="lang" data-v-66ea2533></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0" data-v-66ea2533><code data-v-66ea2533><span class="line" data-v-66ea2533><span data-v-66ea2533>assets=reflectance|expression=(b08-b04)/(b08+b04)</span></span></code></pre></div><p data-v-66ea2533>URL-encode the <code data-v-66ea2533>assets</code> value when building the URL by hand; an unencoded <code data-v-66ea2533>+</code> is read as a space and the request fails. <code data-v-66ea2533>URLSearchParams</code> and <code data-v-66ea2533>encodeURIComponent</code> handle this.</p><p data-v-66ea2533><strong data-v-66ea2533>URL Structure</strong></p><p data-v-66ea2533>Titiler exposes three route levels:</p><table tabindex="0" data-v-66ea2533><thead data-v-66ea2533><tr data-v-66ea2533><th data-v-66ea2533>Route</th><th data-v-66ea2533>Scope</th></tr></thead><tbody data-v-66ea2533><tr data-v-66ea2533><td data-v-66ea2533><code data-v-66ea2533>/raster/collections/{collection}</code></td><td data-v-66ea2533>Mosaic of all items in a collection</td></tr><tr data-v-66ea2533><td data-v-66ea2533><code data-v-66ea2533>/raster/collections/{collection}/items/{item}</code></td><td data-v-66ea2533>One item; can combine bands from several assets</td></tr><tr data-v-66ea2533><td data-v-66ea2533><code data-v-66ea2533>/raster/collections/{collection}/items/{item}/assets/{asset}</code></td><td data-v-66ea2533>One asset of one item</td></tr></tbody></table><p data-v-66ea2533>The examples in this guide use the item route. Tile endpoints follow this pattern:</p><div class="language- vp-adaptive-theme" data-v-66ea2533><button title="Copy Code" class="copy" data-v-66ea2533></button><span class="lang" data-v-66ea2533></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0" data-v-66ea2533><code data-v-66ea2533><span class="line" data-v-66ea2533><span data-v-66ea2533>/raster/collections/{collection}/items/{item}/tiles/WebMercatorQuad/{z}/{x}/{y}.png</span></span></code></pre></div><h3 id="deployment-options" tabindex="-1" data-v-66ea2533>Deployment Options <a class="header-anchor link" href="#deployment-options" aria-label="Permalink to &quot;Deployment Options&quot;" data-v-66ea2533>​</a></h3><p data-v-66ea2533><strong data-v-66ea2533>1. <a href="https://api.explorer.eopf.copernicus.eu/raster/" class="link" target="_blank" rel="noreferrer" data-v-66ea2533>EOPF Explorer TiTiler</a> (Recommended)</strong></p><ul data-v-66ea2533><li data-v-66ea2533><strong data-v-66ea2533>Pre-configured</strong> with STAC catalog integration</li><li data-v-66ea2533><strong data-v-66ea2533>Production-ready</strong> endpoints with optimized performance</li><li data-v-66ea2533><strong data-v-66ea2533>No authentication</strong> required for public data</li><li data-v-66ea2533><strong data-v-66ea2533>Automatic updates</strong> with latest EOPF data</li></ul><p data-v-66ea2533><strong data-v-66ea2533>2. Self-Hosted Instance</strong></p><p data-v-66ea2533>For custom deployments, see the <a href="https://github.com/EOPF-Explorer/titiler-eopf" class="link" target="_blank" rel="noreferrer" data-v-66ea2533>titiler-eopf repository</a> for:</p><ul data-v-66ea2533><li data-v-66ea2533>Docker Compose setup instructions</li><li data-v-66ea2533>Kubernetes/Helm deployment guides</li><li data-v-66ea2533>Environment configuration examples</li><li data-v-66ea2533>Custom data source integration</li></ul><h3 id="next-steps" tabindex="-1" data-v-66ea2533>Next Steps <a class="header-anchor link" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;" data-v-66ea2533>​</a></h3><ol data-v-66ea2533><li data-v-66ea2533><strong data-v-66ea2533>Start with Examples</strong>: Work through each <a href="#integration-examples" class="link" data-v-66ea2533>example</a> to understand the capabilities</li><li data-v-66ea2533><strong data-v-66ea2533>Explore API Documentation</strong>: Use the <a href="https://api.explorer.eopf.copernicus.eu/raster/api.html" class="link" target="_blank" rel="noreferrer" data-v-66ea2533>interactive Swagger UI</a> to test endpoints</li><li data-v-66ea2533><strong data-v-66ea2533>Browse EOPF Data</strong>: Find datasets in the <a href="https://api.explorer.eopf.copernicus.eu/browser" class="link" target="_blank" rel="noreferrer" data-v-66ea2533>STAC Browser</a></li><li data-v-66ea2533><strong data-v-66ea2533>Build Applications</strong>: Integrate Titiler tiles into your web mapping projects</li><li data-v-66ea2533><strong data-v-66ea2533>Community</strong>: Join <a href="https://discourse.eopf.copernicus.eu/c/eopf-explorer/17" class="link" target="_blank" rel="noreferrer" data-v-66ea2533>discussions</a> and contribute to the growing EOPF ecosystem</li></ol><p data-v-66ea2533>For the latest updates and advanced features, follow the <a href="https://github.com/EOPF-Explorer/titiler-eopf" class="link" target="_blank" rel="noreferrer" data-v-66ea2533>Titiler-EOPF project</a> and <a href="https://github.com/EOPF-Explorer" class="link" target="_blank" rel="noreferrer" data-v-66ea2533>EOPF Explorer platform</a> on GitHub.</p>',34)),g(p,{background:"transparent",sectionTitle:"Integration Examples",cards:[{title:"1. RGB Band Combinations",content:"Learn to create true color and false color visualizations using Titiler's tile endpoints with OpenLayers or Leaflet.",features:["True color RGB (B04, B03, B02)","False color infrared composites","Color enhancement formulas","Web mapping integration"],link:{text:"View Example",href:"./rgb",target:"_self"}},{title:"2. Vegetation Indices",content:"Calculate vegetation indices server-side using mathematical expressions and visualize with custom color schemes.",features:["Real-time NDVI calculation","Server-side expressions","Custom color mapping","Environmental monitoring"],link:{text:"View Example",href:"./ndvi",target:"_self"}},{title:"3. Spatial Cropping",content:"Extract specific areas from satellite scenes using bounding box and feature-based spatial operations.",features:["Bounding box cropping","Polygon-based extraction","Coordinate system handling","Export capabilities"],link:{text:"View Example",href:"./crop",target:"_self"}}]})])}}}),T=v(k,[["__scopeId","data-v-66ea2533"]]);export{y as __pageData,T as default};
